<?php
declare(strict_types=1);
require_once __DIR__ . '/config/auth.php';
require_login();

$pdo = db();
$section = preg_replace('/[^a-z]/', '', (string) ($_GET['section'] ?? 'dashboard')) ?: 'dashboard';
$editId = (int) ($_GET['edit'] ?? 0);
$allowedSections = ['dashboard','students','courses','instructors','enrollments','payments','lessons','messages','reports','settings'];
if (!in_array($section, $allowedSections, true)) $section = 'dashboard';
$message = '';
$error = '';

try {
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        verify_csrf();
        $action = (string) ($_POST['action'] ?? '');
        if ($action === 'delete') {
            $table = (string) ($_POST['table'] ?? '');
            $safeTables = ['students','courses','instructors','enrollments','payments','lessons','messages'];
            if (in_array($table, $safeTables, true)) {
                $pdo->prepare("DELETE FROM {$table} WHERE id = ?")->execute([(int) $_POST['id']]);
                $message = 'Record deleted successfully.';
            }
        } elseif ($action === 'student') {
            $id = (int) ($_POST['id'] ?? 0); $name = trim((string) $_POST['name']); $email = trim((string) $_POST['email']);
            if (!$name || !filter_var($email, FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Enter a valid student name and email.');
            if ($id) $pdo->prepare('UPDATE students SET name=?, email=?, phone=?, course=?, status=? WHERE id=?')->execute([$name,$email,trim((string) $_POST['phone']),trim((string) $_POST['course']),$_POST['status'],$id]);
            else $pdo->prepare('INSERT INTO students (name,email,phone,course,status,joined_at) VALUES (?,?,?,?,?,CURDATE())')->execute([$name,$email,trim((string) $_POST['phone']),trim((string) $_POST['course']),$_POST['status']]);
            $message = 'Student saved successfully.'; $section = 'students';
        } elseif ($action === 'course') {
            $id = (int) ($_POST['id'] ?? 0); $title = trim((string) $_POST['title']);
            if (!$title) throw new RuntimeException('A course title is required.');
            if ($id) $pdo->prepare('UPDATE courses SET title=?, description=?, price=?, duration=?, status=? WHERE id=?')->execute([$title,trim((string) $_POST['description']),(float) $_POST['price'],trim((string) $_POST['duration']),$_POST['status'],$id]);
            else $pdo->prepare('INSERT INTO courses (title,description,price,duration,status) VALUES (?,?,?,?,?)')->execute([$title,trim((string) $_POST['description']),(float) $_POST['price'],trim((string) $_POST['duration']),$_POST['status']]);
            $message = 'Course saved successfully.'; $section = 'courses';
        } elseif ($action === 'instructor') {
            $id = (int) ($_POST['id'] ?? 0); $name = trim((string) $_POST['name']); $email = trim((string) $_POST['email']);
            if (!$name || !filter_var($email, FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Enter a valid instructor name and email.');
            if ($id) $pdo->prepare('UPDATE instructors SET name=?, email=?, specialty=?, bio=?, status=? WHERE id=?')->execute([$name,$email,trim((string) $_POST['specialty']),trim((string) $_POST['bio']),$_POST['status'],$id]);
            else $pdo->prepare('INSERT INTO instructors (name,email,specialty,bio,status) VALUES (?,?,?,?,?)')->execute([$name,$email,trim((string) $_POST['specialty']),trim((string) $_POST['bio']),$_POST['status']]);
            $message = 'Instructor saved successfully.'; $section = 'instructors';
        } elseif ($action === 'enrollment') {
            $pdo->prepare('INSERT INTO enrollments (student_id,course_id,status,enrolled_at) VALUES (?,?,?,CURDATE())')->execute([(int) $_POST['student_id'],(int) $_POST['course_id'],$_POST['status']]);
            $message = 'Enrollment recorded.'; $section = 'enrollments';
        } elseif ($action === 'payment') {
            $pdo->prepare('INSERT INTO payments (student_id,amount,method,status,reference,paid_at) VALUES (?,?,?,?,?,CURDATE())')->execute([(int) $_POST['student_id'],(float) $_POST['amount'],trim((string) $_POST['method']),$_POST['status'],trim((string) $_POST['reference'])]);
            $message = 'Payment recorded.'; $section = 'payments';
        } elseif ($action === 'lesson') {
            $pdo->prepare('INSERT INTO lessons (course_id,title,type,resource_url,duration) VALUES (?,?,?,?,?)')->execute([(int) $_POST['course_id'],trim((string) $_POST['title']),$_POST['type'],trim((string) $_POST['resource_url']),trim((string) $_POST['duration'])]);
            $message = 'Lesson added.'; $section = 'lessons';
        } elseif ($action === 'message') {
            $pdo->prepare('INSERT INTO messages (student_id,subject,body) VALUES (?,?,?)')->execute([($_POST['student_id'] ?? '') ?: null,trim((string) $_POST['subject']),trim((string) $_POST['body'])]);
            $message = 'Message sent.'; $section = 'messages';
        } elseif ($action === 'settings') {
            $pdo->prepare('UPDATE settings SET academy_name=?, email=?, phone=?, address=? WHERE id=1')->execute([trim((string) $_POST['academy_name']),trim((string) $_POST['email']),trim((string) $_POST['phone']),trim((string) $_POST['address'])]);
            $message = 'Settings updated.'; $section = 'settings';
        }
    }
} catch (Throwable $exception) { $error = $exception->getMessage(); }

function rows(PDO $pdo, string $sql, array $params = []): array { $statement = $pdo->prepare($sql); $statement->execute($params); return $statement->fetchAll(); }
function initials(string $name): string { $parts = preg_split('/\s+/', trim($name)); return strtoupper(substr($parts[0] ?? 'N',0,1) . substr($parts[1] ?? '',0,1)); }
function status_badge(string $status): string { $type = in_array($status, ['Active','Paid','Published','Completed','Read'], true) ? 'green' : (in_array($status, ['Pending','Draft','On leave'], true) ? 'amber' : 'red'); return '<span class="badge badge-' . $type . '">' . e($status) . '</span>'; }

$students = rows($pdo, 'SELECT * FROM students ORDER BY joined_at DESC');
$courses = rows($pdo, 'SELECT * FROM courses ORDER BY created_at DESC');
$instructors = rows($pdo, 'SELECT * FROM instructors ORDER BY created_at DESC');
$studentOptions = rows($pdo, 'SELECT id,name FROM students ORDER BY name');
$courseOptions = rows($pdo, 'SELECT id,title FROM courses ORDER BY title');
$recent = rows($pdo, 'SELECT name, email, joined_at FROM students ORDER BY joined_at DESC LIMIT 5');
$payments = rows($pdo, 'SELECT p.*, s.name FROM payments p JOIN students s ON s.id=p.student_id ORDER BY paid_at DESC LIMIT 30');
$enrollments = rows($pdo, 'SELECT e.*, s.name student_name, c.title course_title FROM enrollments e JOIN students s ON s.id=e.student_id JOIN courses c ON c.id=e.course_id ORDER BY enrolled_at DESC');
$lessons = rows($pdo, 'SELECT l.*, c.title course_title FROM lessons l JOIN courses c ON c.id=l.course_id ORDER BY l.created_at DESC');
$messages = rows($pdo, 'SELECT m.*, s.name student_name FROM messages m LEFT JOIN students s ON s.id=m.student_id ORDER BY m.created_at DESC');
$settings = $pdo->query('SELECT * FROM settings WHERE id=1')->fetch() ?: ['academy_name'=>'NORAX ACADEMY','email'=>'noraxacademy6@gmail.com','phone'=>'+237688911917 / +237680092008','address'=>'Yaoundé, Cameroon'];
$stats = ['students'=>(int)$pdo->query('SELECT COUNT(*) FROM students')->fetchColumn(),'courses'=>(int)$pdo->query('SELECT COUNT(*) FROM courses')->fetchColumn(),'instructors'=>(int)$pdo->query('SELECT COUNT(*) FROM instructors')->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='Paid'")->fetchColumn()];
$editing = null;
if ($editId && in_array($section, ['students', 'courses', 'instructors'], true)) {
    $editing = $pdo->query('SELECT * FROM ' . $section . ' WHERE id=' . $editId)->fetch() ?: null;
}
$months = []; for ($i=5; $i>=0; $i--) { $date = new DateTime("first day of -{$i} months"); $months[] = ['label'=>$date->format('M'),'value'=>(int)$pdo->query("SELECT COUNT(*) FROM students WHERE MONTH(joined_at)={$date->format('n')} AND YEAR(joined_at)={$date->format('Y')}")->fetchColumn()]; }
$maxMonth = max(1, ...array_column($months, 'value'));
?>
