<div class="metrics"><div class="metric"><div class="metric-top">Total students <span class="metric-icon">♙</span></div><div class="metric-value"><?= number_format($stats['students']) ?></div><div class="metric-note">Active academy learners</div></div><div class="metric"><div class="metric-top">Active courses <span class="metric-icon">▤</span></div><div class="metric-value"><?= number_format($stats['courses']) ?></div><div class="metric-note">Published programs</div></div><div class="metric"><div class="metric-top">Instructors <span class="metric-icon">✦</span></div><div class="metric-value"><?= number_format($stats['instructors']) ?></div><div class="metric-note">Teaching team</div></div><div class="metric"><div class="metric-top">Revenue <span class="metric-icon">₣</span></div><div class="metric-value"><?= number_format($stats['revenue']) ?><small> XAF</small></div><div class="metric-note">Paid transactions</div></div></div>
<div class="dashboard-grid"><div><div class="panel"><div class="panel-head"><h2>Registration overview</h2><span class="muted">Last 6 months</span></div><div class="panel-body"><div class="bars"><?php foreach($months as $month): ?><div class="bar-wrap"><div class="bar <?= $month['label']===date('M')?'active':'' ?>" style="height:<?= max(8,($month['value']/$maxMonth)*100) ?>%" title="<?= $month['value'] ?> registrations"></div><span class="bar-label"><?= e($month['label']) ?></span></div><?php endforeach; ?></div></div></div><div class="panel"><div class="panel-head"><h2>Recent registrations</h2><a href="?section=students">View all →</a></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Course</th><th>Date joined</th><th>Status</th></tr></thead><tbody><?php foreach(array_slice($students,0,5) as $student): ?><tr><td><div class="person"><span class="avatar"><?= e(initials($student['name'])) ?></span><?= e($student['name']) ?></div></td><td><?= e($student['course'] ?: 'Not assigned') ?></td><td><?= e(date('d M Y',strtotime($student['joined_at']))) ?></td><td><?= status_badge($student['status']) ?></td></tr><?php endforeach; if(!$students): ?><tr><td colspan="4" class="muted">No registrations yet.</td></tr><?php endif; ?></tbody></table></div></div></div>
