il" required value="<?= e($editing['email'] ?? '') ?>"></label></div><div class="form-group"><label>Phone<input name="phone" value="<?= e($editing['phone'] ?? '') ?>"></label></div><div class="form-group"><label>Course<input name="course" value="<?= e($editing['course'] ?? '') ?>"></label></div><div class="form-group"><label>Status<select name="status"><option <?= ($editing['status'] ?? '')==='Active'?'selected':'' ?>>Active</option><option <?= ($editing['status'] ?? '')==='Pending'?'selected':'' ?>>Pending</option><option <?= ($editing['status'] ?? '')==='Inactive'?'selected':'' ?>>Inactive</option></select></label></div></div><div class="form-actions"><button class="button button-primary">Save student</button></div></form></div></div>
